import{K as l,a as c,c as i,b as t,k as d,q as s,ac as n}from"./chunks/framework.BSuaGltH.js";const T=JSON.parse('{"title":"Excel 文本清洗、日期与时间计算","description":"用 TRIM、CLEAN、SUBSTITUTE、LEFT、MID、TEXT、DATE、EOMONTH 和 NETWORKDAYS 清洗数据，处理编号、日期类型与时间差。","frontmatter":{"title":"Excel 文本清洗、日期与时间计算","description":"用 TRIM、CLEAN、SUBSTITUTE、LEFT、MID、TEXT、DATE、EOMONTH 和 NETWORKDAYS 清洗数据，处理编号、日期类型与时间差。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"用 TRIM、CLEAN、SUBSTITUTE、LEFT、MID、TEXT、DATE、EOMONTH 和 NETWORKDAYS 清洗数据，处理编号、日期类型与时间差。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup"},"next":{"text":"Excel 数据验证、条件格式与重复检查","link":"/tools/office/excel/validation"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup"},"next":{"text":"Excel 数据验证、条件格式与重复检查","link":"/tools/office/excel/validation"}},"headers":[],"relativePath":"tools/office/excel/text-date.md","filePath":"tools/office/excel/text-date.md"}'),r={name:"tools/office/excel/text-date.md"},E=Object.assign(r,{setup(h){const a={path:"/tools/office/excel/text-date",app:"Excel",title:"把脏文本和日期变成可分析数据",steps:[{tab:"开始",command:"复制",setting:"源值保留 A 列；清洗结果放 B 列",anchor:"walkthrough-1"},{tab:"数据",command:"分列",setting:"日期顺序：YMD；目标区域：空白列",anchor:"walkthrough-2"},{tab:"公式",command:"插入函数",setting:"函数：EOMONTH；日期：2026-10-01",anchor:"walkthrough-3"}]};return(p,e)=>{const o=l("OfficeGuide");return c(),i("div",null,[e[0]||(e[0]=t("h1",{id:"excel-文本清洗、日期与时间计算",tabindex:"-1"},[d("Excel 文本清洗、日期与时间计算 "),t("a",{class:"header-anchor",href:"#excel-文本清洗、日期与时间计算","aria-label":'Permalink to "Excel 文本清洗、日期与时间计算"'},"​")],-1)),e[1]||(e[1]=t("p",null,"数据看起来整齐，不代表类型正确。本篇先在辅助列做转换，核对后再决定是否替换原列，避免把无法恢复的原始编号或日期覆盖掉。",-1)),s(o,{guide:a}),e[2]||(e[2]=n(`<h2 id="clean" tabindex="-1">清理空格与不可见字符 <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;清理空格与不可见字符 {#clean}&quot;">​</a></h2><p>假设 A2 是导入的部门名称，可先用 <code>=TRIM(A2)</code> 清除首尾普通空格，并压缩中间重复普通空格。但 TRIM 不负责清理所有 Unicode 空白，网页复制的数据可能含不间断空格。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=TRIM(CLEAN(SUBSTITUTE(A2,CHAR(160),&quot; &quot;)))</span></span></code></pre></div><p>这能处理一些常见情况，不代表能清除所有异常字符。CLEAN 主要针对特定不可打印字符；中文全角空格等仍需明确替换。真实姓名、地址中的空格可能有意义，不能不加判断全部删除。</p><h2 id="text" tabindex="-1">提取、连接与分列 <a class="header-anchor" href="#text" aria-label="Permalink to &quot;提取、连接与分列 {#text}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>示例公式</th><th>说明</th></tr></thead><tbody><tr><td>取前三个字符</td><td><code>=LEFT(A2,3)</code></td><td>按字符位置提取</td></tr><tr><td>从第 4 位取 2 个字符</td><td><code>=MID(A2,4,2)</code></td><td>起点从 1 开始</td></tr><tr><td>连接部门和编号</td><td><code>=B2&amp;&quot;-&quot;&amp;A2</code></td><td>输出文字</td></tr><tr><td>数值 7 显示成三位文字</td><td><code>=TEXT(A2,&quot;000&quot;)</code></td><td>结果是文本 <code>007</code></td></tr><tr><td>替换指定文字</td><td><code>=SUBSTITUTE(A2,&quot;旧部门&quot;,&quot;新部门&quot;)</code></td><td>注意是否只应修改完整字段</td></tr></tbody></table><p>“数据 → 分列”适合把稳定分隔符的数据拆开。分列前确认右边列为空或设置输出位置，否则可能覆盖已有内容；在导入向导中把编号列设为文本。支持 TEXTSPLIT 等新函数的版本也可以用动态数组拆分，但共享给旧版用户前要检查兼容性。</p><h2 id="dates" tabindex="-1">日期是真实数值还是文字 <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;日期是真实数值还是文字 {#dates}&quot;">​</a></h2><p>对日期单元格执行 <code>=ISNUMBER(B2)</code>，真实 Excel 日期通常返回 TRUE。把文字设置成“日期格式”不一定能转换为真实日期。若来源为严格 <code>2026-10-15</code> 格式，可明确拆分：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=DATE(VALUE(LEFT(A2,4)),VALUE(MID(A2,6,2)),VALUE(RIGHT(A2,2)))</span></span></code></pre></div><p>此公式假设长度和位置都正确，而且 DATE 会对部分越界月份或天数做进位，并非严格日期校验器。导入后还应对比转换后的年月日与原始字段，非法值不能悄悄变成另一天。来源混用月/日/年和日/月/年时，优先在 Power Query 中指定区域设置。</p><h2 id="time" tabindex="-1">月末、时间差与工作日 <a class="header-anchor" href="#time" aria-label="Permalink to &quot;月末、时间差与工作日 {#time}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=EOMONTH(DATE(2026,10,15),0)</span></span>
<span class="line"><span>=DATE(2026,11,1)-DATE(2026,10,1)</span></span>
<span class="line"><span>=NETWORKDAYS(DATE(2026,11,2),DATE(2026,11,6))</span></span></code></pre></div><p>第一式结果格式化为日期后是 2026-10-31，第二式为 31 天，第三式在没有节假日参数时是 5 个工作日。NETWORKDAYS 默认周六、周日不算工作日，且计算区间包含符合条件的首尾日期；本地节假日与调休需要另外维护，不能认为它自动知道所有法定安排。</p><p>Excel 时间是一天的分数。开始时间 A2、结束时间 B2 都包含完整日期时，<code>=(B2-A2)*24</code> 得到小时数。只保存时分会丢失跨日信息；<code>MOD(B2-A2,1)</code> 只适合明确假设不超过一天的情况，不能用来掩盖负时间或多天记录。总时长显示可用 <code>[h]:mm</code>，避免超过 24 小时后显示回绕。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>清洗 <code>&quot; 运营 &quot;</code> 后应为“运营”；把文字 <code>2026-10-15</code> 转成日期后，用 YEAR、MONTH、DAY 分别得到 2026、10、15。最后计算从 2026-10-31 22:00 到 2026-11-01 02:30 的时间差，应为 4.5 小时。</p><p>把文本辅助列和数值辅助列标清用途，避免将 <code>TEXT</code> 的漂亮输出拿去做时间区间比较。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把脏文本和日期变成可分析数据 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把脏文本和日期变成可分析数据 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先保留原始输入 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先保留原始输入 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 复制。</strong></p><p>新建清洗练习表，在 A2 输入带前后普通空格的“ 运营 ”，B2 输入 =TRIM(A2)。用 LEN 比较前后长度，确认只是去除了多余普通空格。遇到不间断空格，可先用 SUBSTITUTE 替换 CHAR(160)，但不要把合法的产品名内部空格一概删除。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：按来源约定转换日期 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：按来源约定转换日期 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据 → 分列。</strong></p><p>把类似 2026-10-01 的文本日期复制到空白测试列，选择“数据 → 分列”，在最后一步按来源顺序选日期 YMD。确认目标区域不会覆盖右侧数据。随后用 ISNUMBER 检查结果，再设置显示格式；仅把数字格式改为日期，并不保证文本已转换。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用已知日期检查转换结果 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用已知日期检查转换结果 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：公式 → 插入函数。</strong></p><p>对已转换的日期输入 =EOMONTH(日期单元格,0)，结果应为 2026-10-31，必要时给结果设置日期格式。再用 YEAR、MONTH、DAY 分别检查年、月、日。对于 03/04/2026 一类有歧义的原文，先确认是日/月还是月/日，不要只凭系统自动识别。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>长编号发生精度损失后，把格式改成文本不能恢复丢失位数；应回到原始文本来源重新导入。日期和编号的转换要分列处理，不能一套规则清洗所有字段。</p>`,31))])}}});export{T as __pageData,E as default};
